bool isValid(string s) {
    stack<char> st;
    unordered_map<char, char> m = {
        {')', '('}, {']', '['}, {'}', '{'}
    };
    for (char c : s) {
        if (m.count(c)) { // 是右括号
            if (st.empty() || st.top() != m[c]) return false;
            st.pop();
        } else {
            st.push(c);
        }
    }
    return st.empty();
}
// 哈希表映射配对 | 右括号检查栈顶 | 最终栈为空
